def solve(s: str) -> int:
    # Handle possible lower‑case input by converting to upper case.
    s = s.upper()
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    # Process characters from right to left.
    for ch in reversed(s):
        val = values.get(ch, 0)
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total

