def solve(s):
    """Run-length encoding: return list of [character, count] for each maximal run.
    Accepts any input convertible to string; None returns empty list.
    """
    if s is None:
        return []
    if not isinstance(s, str):
        s = str(s)
    if not s:
        return []
    res = []
    cur = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = ch
            cnt = 1
    res.append([cur, cnt])
    return res

