    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0), (-1,0), (0,1), (0,-1)):
