def solve(tokens):
    stack = []
    for tok in tokens:
        if tok.lstrip('-').isdigit():
            stack.append(int(tok))
        else:
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            elif tok == '/':
                # Truncate toward zero
                stack.append(int(a / b))
            else:
                raise ValueError('invalid operator')
    return stack[0] if stack else 0

