    """Evaluate an expression in Reverse Polish Notation.
    tokens: list of strings, each either an integer (possibly signed) or one of '+', '-', '*', '/'.
    Division truncates toward zero as required.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
